import copy, json, math; from work import evaluate
p={'base_unit':'m','units':{'m':1,'cm':0.01},'unique':True}
r={'rows':[{'id':'a','amount':2,'unit':'cm'},{'id':'a','amount':3},{'id':'','amount':1},{'id':'b','amount':True},{'id':'c','amount':float('inf')},{'id':'d','amount':1,'unit':'bad'}]}
rc,pc=copy.deepcopy(r),copy.deepcopy(p)
out=evaluate(r,p)
assert out=={'ok':False,'records':[],'errors':[{'row':1,'cause':'duplicate'},{'row':2,'cause':'id'},{'row':3,'cause':'amount'},{'row':4,'cause':'amount'},{'row':5,'cause':'unit'}]}
assert r==rc and p==pc
assert evaluate({'rows':[{'id':'x','amount':0},{'id':'y','amount':250,'unit':'cm'}]},p)=={'ok':True,'records':[{'id':'x','amount':0,'unit':'m'},{'id':'y','amount':2.5,'unit':'m'}],'errors':[]}
print('edge checks passed')

